    class YieldFailTaskInBatches(luigi.Task):
        def run(self):
            for i in range(5):
                yield [
                    FailTask(i, j)
                    for j in range(2)
                ]


    class YieldAllFailTasksAtOnce(luigi.Task):
        def run(self):
            yield [
                FailTask(i, j)
                for j in range(2)
                for i in range(5)
            ]

    class FailTask(luigi.Task):
        i = luigi.IntParameter()
        j = luigi.IntParameter()

